UPDATE banks SET attrs = jsonb_build_object('bankBranch', 'Main Branch', 'City', 'Makati', 'state', 'Metro Manila', 'Country', 'Philippines', 'mobile', '+63 2 8888 0000', 'email', lower(code) || '@bank.example', 'AddressLine1', 'Ayala Avenue', 'category', 'Universal Bank') || attrs WHERE NOT attrs ? 'bankBranch';
UPDATE insurance_companies SET attrs = jsonb_build_object('insuranceCompanyDescription', name || ' - non-life insurer', 'city', 'Makati', 'state', 'Metro Manila', 'country', 'Philippines') || attrs, address = COALESCE(address, 'Ayala Avenue, Makati City'), contact_phone = COALESCE(contact_phone, '+63 2 8888 0000') WHERE NOT attrs ? 'city';
UPDATE signatories SET attrs = jsonb_build_object('signatoryCode', 'SIG-' || lpad(id::text, 3, '0'), 'signatoryDescription', COALESCE(designation, 'Authorised signatory')) || attrs WHERE NOT attrs ? 'signatoryCode';
UPDATE branches SET attrs = jsonb_build_object('CompanyName', 'BrokerVerse Insurance Brokers, Inc.', 'EmailID', lower(code) || '@brokerverse.example', 'City', split_part(address, ' City', 1), 'State', CASE code WHEN 'CEB' THEN 'Cebu' WHEN 'DAV' THEN 'Davao del Sur' ELSE 'Metro Manila' END, 'Country', 'Philippines', 'PhoneNumber', '+63 2 8888 1200') || attrs WHERE NOT attrs ? 'CompanyName';
